def _merkle_leaf_hash(event_obj: Dict[str, Any]) -> bytes:
    return hashlib.sha256(b"\x00" + crypto.canonicalize(event_obj)).digest()


def _merkle_parent_hash(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()


def _merkle_root_and_path(leaf_hashes, index):
    """返回 (root_hex, path)：path 自叶向根，每项 {side, hash}，
    side 为兄弟节点所在侧（left/right），hash 为兄弟哈希小写 hex。"""
    level = list(leaf_hashes)
    path = []
    idx = index
    while len(level) > 1:
        if len(level) % 2 == 1:
            level = level + [level[-1]]
        sibling = idx ^ 1
        path.append({
            "side": "left" if sibling < idx else "right",
            "hash": level[sibling].hex(),
        })
        level = [
            _merkle_parent_hash(level[i], level[i + 1])
            for i in range(0, len(level), 2)
        ]
        idx //= 2
    return level[0].hex(), path
